import { h } from '@last-orbit/ui/dom.js';
const paths = {
  launch: 'M12 2c4 3 5 8 4 13l-4 3-4-3c-1-5 0-10 4-13zM8 15l-3 3 1 4 3-2M16 15l3 3-1 4-3-2M12 8v3',
  workshop: 'M14 6a4 4 0 0 0 5 5l2 2-8 8-2-2a4 4 0 0 0-5-5L3 11l8-8zM7 17l-3 3',
  armory: 'M12 2v4M12 18v4M2 12h4M18 12h4M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0M12 10v4M10 12h4',
  ships: 'M12 2l3 7 6 3-6 2-3 8-3-8-6-2 6-3z',
  contracts: 'M8 3h8v3H8zM6 5H4v17h16V5h-2M8 11h8M8 15h8M8 19h5',
  pause: 'M8 5v14M16 5v14',
  gear: 'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 1v4M12 19v4M4.2 4.2l2.8 2.8M17 17l2.8 2.8M1 12h4M19 12h4M4.2 19.8 7 17M17 7l2.8-2.8',
  close: 'M5 5l14 14M19 5L5 19',
  reroll: 'M20 11a8 8 0 0 0-14-5L4 8M4 3v5h5M4 13a8 8 0 0 0 14 5l2-2M20 21v-5h-5',
  check: 'M4 12l5 5L20 6',
  lock: 'M6 11h12v10H6zM8 11V7a4 4 0 0 1 8 0v4',
  play: 'M7 4l13 8-13 8z',
  home: 'M3 11l9-8 9 8M5 9v12h14V9',
  chevron: 'M9 5l7 7-7 7',
};
export function uiIcon(id) {
  const path = paths[id] || paths.ships;
  return h('span.ui-icon', { 'aria-hidden': 'true', html: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="square" stroke-linejoin="miter" focusable="false"><path d="${path}"/></svg>` });
}

// Distinct silhouettes at HUD scale: rough mineral clusters versus cast, stacked ingots.
// currentColor keeps every surface tied to the authoritative material palette.
export function materialSVG(kind = 'ore') {
  const art = kind === 'bar' ? `
    <path d="M3 18L8 10L24 8L29 15L29 21L10 26L3 23Z" fill="#07131e" stroke="#07131e" stroke-width="2" stroke-linejoin="round"/>
    <path d="M4 18L10 16L28 15L28 21L10 25L4 22Z" fill="currentColor"/>
    <path d="M10 19L28 15V21L10 25Z" fill="#000" opacity=".38"/>
    <path d="M4 18L10 19V25L4 22Z" fill="#000" opacity=".16"/>
    <path d="M5 17L9 10L23 8L27 14L10 19Z" fill="currentColor"/>
    <path d="M5 17L9 10L23 8L27 14L10 19Z" fill="#fff" opacity=".27"/>
    <path d="M10 10L23 8L26 13L13 16L9 14Z" fill="currentColor" stroke="#07131e" stroke-width=".8"/>
    <path d="M9 10L23 8M5 17L10 19L27 14" fill="none" stroke="#fff" stroke-opacity=".65" stroke-width="1.1"/>
    <path d="M16 11L19 10.5L21 12L18 13Z" fill="#07131e" opacity=".55"/>
    <path d="M13 21L25 18" stroke="currentColor" stroke-width="1" opacity=".85"/>
    <path d="M22 6V10M20 8H24" stroke="#fff" stroke-width="1" opacity=".8"/>`
    : `
    <path d="M3 16L7 8L14 5L22 7L27 13L29 23L22 28L10 27L3 23Z" fill="#172330" stroke="#07131e" stroke-width="2" stroke-linejoin="round"/>
    <path d="M4 16L8 9L14 6L19 12L14 20L7 22Z" fill="currentColor"/>
    <path d="M14 6L22 8L26 13L19 17L19 12Z" fill="currentColor"/>
    <path d="M14 6L22 8L26 13L19 12Z" fill="#fff" opacity=".32"/>
    <path d="M4 16L7 22L14 20L10 26L4 23Z" fill="#000" opacity=".3"/>
    <path d="M14 20L19 12L26 13L23 21L18 26L10 26Z" fill="currentColor"/>
    <path d="M19 12L26 13L23 21L14 20Z" fill="#000" opacity=".24"/>
    <path d="M23 21L27 17L28 23L22 27L18 26Z" fill="currentColor"/>
    <path d="M7 12L11 9L14 11L11 16L7 17Z" fill="#fff" opacity=".48"/>
    <path d="M8 10L13 7M16 23L19 20L22 21M23 10L25 13" stroke="#fff" stroke-opacity=".65" stroke-width="1.1" fill="none"/>
    <path d="M10 18L14 20L12 24M19 12L17 9" stroke="#07131e" stroke-width="1.2" fill="none"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" aria-hidden="true" focusable="false">${art}</svg>`;
}
export function materialIcon(material, kind = 'ore') {
  // Use the pixel-art slices where there is a close visual match; later exotic tiers retain
  // the colour-aware vector silhouette so no resource becomes misleadingly identical.
  const atlasMaterial = { iron: 'iron', copper: 'gold', silver: 'silver', gold: 'gold', cobalt: 'cobalt', titanium: 'silver', iridium: 'iridium' }[material.id || material.material];
  if (atlasMaterial) return h('span.material-icon.pixel-material.' + kind, { 'aria-hidden': 'true', style: `--mat:${material.color};color:var(--mat)` }, gameIcon(kind, atlasMaterial, 'material-pixel', '▰'));
  return h('span.material-icon.' + kind, { 'aria-hidden': 'true', style: `--mat:${material.color};color:var(--mat)`, html: materialSVG(kind) });
}

// Pixel-art game icons. Runtime uses the pre-sliced files rather than CSS atlas offsets.
// This avoids one failed atlas request blanking every icon and removes sprite-position alignment drift.
const PIXEL_ICON_FILE = {
  // Weapons.
  'weapon:cannon': 'data:image/png;base64,', 'weapon:laser': 'data:image/png;base64,', 'weapon:missile': 'data:image/png;base64,', 'weapon:tesla': 'data:image/png;base64,',
  'weapon:rail': 'data:image/png;base64,', 'weapon:plasma': 'data:image/png;base64,', 'weapon:mine': 'data:image/png;base64,', 'weapon:prism': 'data:image/png;base64,',
  // Drones and Foundry supplies.
  'drone:attack': 'data:image/png;base64,', 'drone:missile': 'data:image/png;base64,', 'drone:repair': 'data:image/png;base64,', 'drone:collect': 'data:image/png;base64,',
  'drone:shield': 'data:image/png;base64,', 'drone:intercept': 'data:image/png;base64,', 'support:burst': 'data:image/png;base64,', 'support:repair': 'data:image/png;base64,',
  'support:salvage': 'data:image/png;base64,',
  // Active abilities.
  'ability:overdrive': 'data:image/png;base64,', 'ability:emp': 'data:image/png;base64,', 'ability:barrage': 'data:image/png;base64,', 'ability:aegis': 'data:image/png;base64,',
  'ability:strike': 'data:image/png;base64,', 'ability:slow': 'data:image/png;base64,', 'ability:swarm': 'data:image/png;base64,', 'ability:hole': 'data:image/png;base64,',
  'ability:charge': 'data:image/png;base64,',
  // Module slot families.
  'module:weaponmod': 'data:image/png;base64,', 'module:reactor': 'data:image/png;base64,', 'module:targeting': 'data:image/png;base64,', 'module:shieldgen': 'data:image/png;base64,',
  'module:engine': 'data:image/png;base64,', 'module:dronebay': 'data:image/png;base64,', 'module:processor': 'data:image/png;base64,', 'module:experimental': 'data:image/png;base64,',
  // Currencies / long-term resources.
  'currency:credits': 'data:image/png;base64,', 'currency:scrap': 'data:image/png;base64,', 'currency:data': 'data:image/png;base64,', 'currency:shards': 'data:image/png;base64,',
  'currency:sigils': 'data:image/png;base64,', 'currency:frags': 'data:image/png;base64,', 'currency:matter': 'data:image/png;base64,', 'currency:cores': 'data:image/png;base64,',
  // Miscellaneous systems/assets.
  'misc:energy': 'data:image/png;base64,', 'misc:blueprint': 'data:image/png;base64,', 'misc:salvage': 'data:image/png;base64,',
  'misc:damage': 'data:image/png;base64,', 'misc:multishot': 'data:image/png;base64,', 'misc:critical': 'data:image/png;base64,', 'misc:armour': 'data:image/png;base64,',
  'misc:repair': 'data:image/png;base64,', 'misc:shield-recharge': 'data:image/png;base64,', 'misc:thrusters': 'data:image/png;base64,', 'misc:barrier': 'data:image/png;base64,',
  // Ore/bar silhouettes. Later material tiers keep the colour-aware SVG fallback.
  'ore:iron': 'data:image/png;base64,', 'ore:cobalt': 'data:image/png;base64,', 'ore:iridium': 'data:image/png;base64,', 'ore:silver': 'data:image/png;base64,',
  'ore:tungsten': 'data:image/png;base64,', 'ore:osmium': 'data:image/png;base64,', 'ore:gold': 'data:image/png;base64,',
  'bar:iron': 'data:image/png;base64,', 'bar:cobalt': 'data:image/png;base64,', 'bar:iridium': 'data:image/png;base64,', 'bar:silver': 'data:image/png;base64,',
  'bar:tungsten': 'data:image/png;base64,', 'bar:osmium': 'data:image/png;base64,', 'bar:gold': 'data:image/png;base64,',
};

const UPGRADE_ART = {
  dmg: 'damage', rate: 'multishot', critc: 'critical', critd: 'critical', bossd: 'critical', multi: 'multishot', pierce: 'damage', pspeed: 'thrusters', blast: 'damage', apen: 'damage',
  hull: 'armour', regen: 'repair', shield: 'barrier', srech: 'shield-recharge', armor: 'armour', move: 'thrusters', barrier: 'barrier',
  credit: 'credits', scrapc: 'scrap', scrapg: 'scrap', datag: 'data', focus: 'critical', combo: 'damage',
  autofire: 'multishot', autopilot: 'thrusters', buy10: 'salvage', buy25: 'salvage', buy100: 'salvage', buymax: 'salvage', autopush: 'overdrive', scanner: 'targeting',
};
const BOON_ART = {
  b_dmg: 'damage', b_rate: 'multishot', b_crit: 'critical', b_critd: 'critical', b_pierce: 'damage', b_multi: 'multishot', b_critex: 'damage', b_split: 'multishot',
  b_drone: 'swarm', b_droned: 'swarm', b_regen: 'shield-recharge', b_hull: 'armour', b_shield: 'barrier', b_cred: 'credits', b_scrap: 'scrap', b_data: 'data',
  b_boss: 'critical', b_blast: 'damage', b_energy: 'energy', b_cd: 'slow', b_killex: 'damage', b_return: 'critical', b_focus: 'critical', b_shard: 'shards',
};
const TAG_ART = { offence: 'damage', crit: 'critical', drone: 'swarm', defence: 'barrier', economy: 'credits', boss: 'critical' };

function artKey(kind, id) {
  if (kind === 'upgrade') {
    const k = UPGRADE_ART[id];
    if (!k) return null;
    if (['credits', 'scrap', 'data', 'shards'].includes(k)) return 'currency:' + k;
    if (k === 'overdrive' || k === 'slow' || k === 'swarm') return 'ability:' + k;
    if (k === 'targeting') return 'module:targeting';
    return 'misc:' + k;
  }
  if (kind === 'boon') {
    const k = BOON_ART[id];
    if (!k) return null;
    if (['credits', 'scrap', 'data', 'shards'].includes(k)) return 'currency:' + k;
    if (k === 'slow' || k === 'swarm') return 'ability:' + k;
    return 'misc:' + k;
  }
  if (kind === 'tag') {
    const k = TAG_ART[id] || 'critical';
    if (k === 'credits') return 'currency:credits';
    if (k === 'swarm') return 'ability:swarm';
    return 'misc:' + k;
  }
  return kind + ':' + id;
}

/** Pixel-art icon from a 'kind:id' key such as 'weapon:laser' or 'misc:damage'. */
export function iconKey(key, className = '', fallback = '◇') { const i = key.indexOf(':'); return gameIcon(key.slice(0, i), key.slice(i + 1), className, fallback); }

/** Render one normalized pixel-art slice. Falls back to a text glyph when unmapped or unavailable. */
export function gameIcon(kind, id, className = '', fallback = '◇') {
  // Credits use the original C-shaped currency mark, not the newer ingot artwork.
  const key = artKey(kind, id), file = key === 'currency:credits' ? null : key && PIXEL_ICON_FILE[key];
  if (!file) {
    const fb = h('span.game-icon-fallback', { 'aria-hidden': 'true' }, fallback);
    if (className) fb.classList.add(...className.split(/\s+/).filter(Boolean));
    return fb;
  }
  const el = h('span.game-icon', { 'aria-hidden': 'true', 'data-game-icon': key, 'data-game-icon-file': file });
  const img = h('img', { src: file, alt: '', draggable: false, decoding: 'async' });
  // A bad/missing asset should degrade to a visible glyph rather than silently blanking the slot.
  if (typeof img.addEventListener === 'function') img.addEventListener('error', () => { el.classList.add('missing'); el.textContent = fallback; });
  el.append(img);
  if (className) el.classList.add(...className.split(/\s+/).filter(Boolean));
  return el;
}

/** Convenience for persistent anomaly/run-choice tags when the exact choice has no dedicated tile. */
export function tagIcon(tag, className = '') { return gameIcon('tag', tag, className); }
